import sys, json
class Solution:
    def trap(self, height):
        result, left, right, level = 0, 0, len(height)-1, 0
        while left < right:
            if height[left] < height[right]:
                lower=height[left]; left+=1
            else:
                lower=height[right]; right-=1
            level=max(level,lower); result+=level-lower
        return result
if __name__ == "__main__":
    args=json.loads(sys.stdin.readline()); print(json.dumps(Solution().trap(args[0])))

